import sys

def solve(M, S, steps):
    MOD = 1 << S
    current_power = 1
    result = []

    for step in steps:
        if step == '+':
            current_power += 1
            if current_power >= MOD:
                current_power %= MOD
            result.append(step)
        elif step == 'x':
            if current_power * 2 >= MOD:
                result.append('o')
            else:
                current_power *= 2
                result.append(step)

    return ''.join(result)

