def max_discharge(M, S, steps):
    MOD = 1 << S
    dp = [[0] * (S + 1) for _ in range(M + 1)]
    path = [[''] * (S + 1) for _ in range(M + 1)]

    for i in range(1, M + 1):
        for j in range(S + 1):
            if steps[i - 1] == '+':
                dp[i][j] = (dp[i - 1][j] + 1) % MOD
                path[i][j] = path[i - 1][j] + '+'
            elif steps[i - 1] == 'x':
                dp[i][j] = (dp[i - 1][j] * 2) % MOD
                path[i][j] = path[i - 1][j] + 'x'

            # Try converting the current step to 'o'
            if j > 0:
                if dp[i][j] < dp[i - 1][j - 1]:
                    dp[i][j] = dp[i - 1][j - 1]
                    path[i][j] = path[i - 1][j - 1] + 'o'

    return path[M][S]

